package com.pocketmusic.android;

import android.app.*;
import android.content.Intent;
import android.os.*;
import android.net.Uri;
import android.view.WindowManager;
import android.webkit.*;
import android.widget.*;
import java.util.UUID;
import java.util.concurrent.*;

/** Visible, isolated Music login: capture context, validate identity, then commit encrypted session. */
public final class YouTubeLoginActivity extends Activity {
 private static boolean profileInitialized;
 private static final String MUSIC="https://music.youtube.com/",LOGIN="https://accounts.google.com/ServiceLogin?continue=https%3A%2F%2Fmusic.youtube.com";
 private WebView web;private TextView status,address;private Button retry;private ProgressBar progress;
 private boolean visible,validating,capturing,failed;private volatile boolean cancelled;private volatile int epoch;private int attempts;
 private final String process="login-"+UUID.randomUUID();private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private final Runnable poll=new Runnable(){public void run(){if(!visible||cancelled||validating||isFinishing())return;probe();handler.postDelayed(this,500);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);if(!profileInitialized){if(Build.VERSION.SDK_INT>=28)WebView.setDataDirectorySuffix("youtube-login");profileInitialized=true;}getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);
  if(getIntent().getBooleanExtra("disconnect",false)){worker.execute(()->{YouTubeSession.disconnect(this);runOnUiThread(()->CookieManager.getInstance().removeAllCookies(removed->{CookieManager.getInstance().flush();WebStorage.getInstance().deleteAllData();Toast.makeText(this,"YouTube disconnected.",Toast.LENGTH_LONG).show();finish();}));});return;}
  int padding=Math.round(16*getResources().getDisplayMetrics().density);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(GlassTheme.BG);root.setPadding(padding,padding,padding,padding);root.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(padding,in.getSystemWindowInsetTop()+padding,padding,in.getSystemWindowInsetBottom()+padding);return in;});
  address=new TextView(this);address.setTextColor(GlassTheme.TEXT);address.setText("Connect YouTube Music");root.addView(address);status=new TextView(this);status.setTextColor(GlassTheme.MUTED);status.setText("Complete Google's sign-in and verification. Your selected YouTube Music account will be verified and saved automatically.");root.addView(status);
  LinearLayout actions=new LinearLayout(this);retry=new Button(this);retry.setText("Retry connection");retry.setOnClickListener(v->{if(validating)return;failed=false;attempts=0;epoch++;capturing=false;if(MusicLoginFlow.trusted(web.getUrl()))probe();else web.loadUrl(MUSIC);});actions.addView(retry,new LinearLayout.LayoutParams(0,-2,1));Button close=new Button(this);close.setText("Cancel");close.setOnClickListener(v->{cancelled=true;AccountMusic.cancel(process);finish();});actions.addView(close);root.addView(actions);
  LinearLayout recovery=new LinearLayout(this);Button music=new Button(this);music.setText("Open YouTube Music");music.setOnClickListener(v->{if(!validating){web.stopLoading();web.loadUrl(MUSIC);}});recovery.addView(music,new LinearLayout.LayoutParams(0,-2,1));Button choose=new Button(this);choose.setText("Choose account");choose.setOnClickListener(v->{if(!validating){web.stopLoading();web.loadUrl("https://accounts.google.com/AccountChooser?continue=https%3A%2F%2Fmusic.youtube.com");}});recovery.addView(choose,new LinearLayout.LayoutParams(0,-2,1));root.addView(recovery);
  progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);root.addView(progress,new LinearLayout.LayoutParams(-1,Math.round(3*getResources().getDisplayMetrics().density)));
  web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,true);
  web.setWebChromeClient(new WebChromeClient(){public void onProgressChanged(WebView view,int value){progress.setProgress(value);progress.setVisibility(value>=100?android.view.View.GONE:android.view.View.VISIBLE);}});
  web.setWebViewClient(new WebViewClient(){
   public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){if(!request.isForMainFrame())return false;String url=request.getUrl().toString();if(LoginPolicy.browsable(url))return false;if(url.startsWith("intent:")&&LoginPolicy.allowed(view.getUrl())){try{Intent intent=Intent.parseUri(url,Intent.URI_INTENT_SCHEME);String fallback=intent.getStringExtra("browser_fallback_url");if(LoginPolicy.allowed(fallback)){view.loadUrl(fallback);return true;}intent.setComponent(null);intent.setSelector(null);intent.setAction(Intent.ACTION_VIEW);intent.addCategory(Intent.CATEGORY_BROWSABLE);intent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK);if(intent.resolveActivity(getPackageManager())!=null){startActivity(intent);status.setText("Complete verification in the opened app, then return here and Open YouTube Music.");return true;}}catch(Exception ignored){}}status.setText("This verification handoff couldn't open. Return to Google sign-in or Open YouTube Music after verification.");return true;}
   public void onPageStarted(WebView view,String url,android.graphics.Bitmap icon){epoch++;attempts=0;capturing=false;failed=false;address.setText(LoginPolicy.browsable(url)?"Page · "+Uri.parse(url).getHost():"Connect YouTube Music");if(!validating)status.setText(MusicLoginFlow.trusted(url)?"Waiting for YouTube Music to finish connecting your account…":"Complete Google's sign-in and verification, then return to YouTube Music.");}
   public void onPageFinished(WebView view,String url){CookieManager.getInstance().flush();probe();}
   public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame()&&!validating)status.setText("The sign-in page couldn't load. Check your connection, then Retry connection. Google may reject embedded sign-in on some devices.");}
  });root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);if(state==null||web.restoreState(state)==null)web.loadUrl(LOGIN);
 }
 private void probe(){if(web==null||validating||capturing||cancelled||failed||!MusicLoginFlow.trusted(web.getUrl()))return;if(attempts++>=20){failed=true;status.setText("YouTube Music hasn't finished connecting this session. Finish sign-in or choose the account on the page, then Retry connection.");return;}capturing=true;int token=epoch;handler.postDelayed(()->{if(token==epoch)capturing=false;},1000);
  web.evaluateJavascript(MusicLoginFlow.CONFIG_SCRIPT,result->{if(token!=epoch||cancelled||validating||isDestroyed()||!MusicLoginFlow.trusted(web.getUrl()))return;capturing=false;try{String cookie=CookieManager.getInstance().getCookie(MUSIC);SessionAuth candidate=MusicLoginFlow.capture(cookie,result);validate(candidate);}catch(Exception notReady){/* Bounded retry; no cookies or page contents are logged. */}});
 }
 private void validate(SessionAuth candidate){if(validating||cancelled)return;validating=true;retry.setEnabled(false);status.setText("Verifying the selected YouTube Music account…");int token=epoch;worker.execute(()->{try{SessionAuth connected=MusicLoginFlow.connect(this,candidate,process,()->cancelled||epoch!=token);runOnUiThread(()->{if(cancelled||isDestroyed())return;status.setText("Connected as "+connected.accountName);Toast.makeText(this,"Connected as "+connected.accountName,Toast.LENGTH_LONG).show();setResult(RESULT_OK);finish();});}catch(Exception error){runOnUiThread(()->{if(cancelled||isDestroyed())return;if(token!=epoch){validating=false;retry.setEnabled(true);failed=false;attempts=0;probe();return;}validating=false;failed=true;retry.setEnabled(true);String message=error.getMessage()==null?"":error.getMessage();status.setText(message.contains("secure storage")?"Account verified, but secure storage failed. Retry connection.":DownloadErrors.rateLimited(message)?"YouTube is limiting connections. Wait a minute, then Retry connection.":"Account not saved: YouTube Music couldn't verify the selected account. Finish sign-in or Choose account, then Retry connection. Your previous saved account is kept.");});}});}
 @Override protected void onSaveInstanceState(Bundle state){if(web!=null)web.saveState(state);super.onSaveInstanceState(state);}
 @Override protected void onPause(){visible=false;handler.removeCallbacks(poll);if(web!=null){CookieManager.getInstance().flush();web.onPause();}super.onPause();}
 @Override protected void onResume(){super.onResume();visible=true;if(web!=null){web.onResume();handler.removeCallbacks(poll);handler.post(poll);}}
 @Override protected void onDestroy(){cancelled=true;handler.removeCallbacksAndMessages(null);AccountMusic.cancel(process);if(web!=null){web.stopLoading();CookieManager.getInstance().flush();web.destroy();}worker.shutdownNow();super.onDestroy();}
}
